1	import type { Item } from "./policy.js";
2	import { reimbursementRateOf } from "./reimbursement-clause.js";
3	
4	export interface Damage {
5	  readonly itemType: string;
6	  readonly amount: number;
7	}
8	
9	export interface ClaimResult {
10	  readonly payout: number;
11	  readonly remainingCap: number;
12	}
13	
14	/**
15	 * The policyholder bears a deductible on each damaged item, so an incident
16	 * that damages several items bears it several times -- once per damage
17	 * entry, which is why the payout is accumulated per entry rather than off
18	 * the incident's total.
19	 */
20	const DEDUCTIBLE = 100;
21	
22	/**
23	 * A payout is money the MHPCO pays out, so it floors at nothing: the
24	 * deductible can reduce a payout to zero, but a damage smaller than the
25	 * deductible never turns into a debt owed to the MHPCO.
26	 */
27	const NOTHING_PAID_OUT = 0;
28	
29	/**
30	 * The insured item a damage entry hit. An entry naming a type the policy does
31	 * not cover stands in as a bare item for now; the rejection rule that will
32	 * turn it away is still to come.
33	 */
34	function damagedItem(items: readonly Item[], damage: Damage): Item {
35	  return items.find((item) => item.type === damage.itemType) ?? {
36	    type: damage.itemType,
37	  };
38	}
39	
40	/** What one damage settles at: the reimbursed share, less the deductible. */
41	function payoutForDamage(items: readonly Item[], damage: Damage): number {
42	  const reimbursed =
43	    damage.amount * reimbursementRateOf(damagedItem(items, damage));
44	  return Math.max(reimbursed - DEDUCTIBLE, NOTHING_PAID_OUT);
45	}
46	
47	/**
48	 * Settling an incident against the policy that covers it. The special
49	 * clauses are read off the damaged item; the rejection rules will be too,
50	 * once their examples are active.
51	 */
52	export function claim(
53	  items: readonly Item[],
54	  damages: readonly Damage[],
55	  remainingCap: number,
56	): ClaimResult {
57	  const payout = damages.reduce(
58	    (total, damage) => total + payoutForDamage(items, damage),
59	    0,
60	  );
61	  return { payout, remainingCap: remainingCap - payout };
62	}
